// Хук фильтрации тактической карточки врага. Грузимся после
// Reforged/Hardened, поэтому видим итоговый тултип целиком и
// просто отфильтровываем лишние записи по их id/type.
::Legacy.MH.hook("scripts/entity/tactical/actor", function(q) {
    q.getTooltip = @(__original) function( _targetedWithSkill = null ) {
        local ret = __original(_targetedWithSkill);

        local mode = ::Legacy.getEnemyTooltipMode();
        if (mode == "Off") return ret;

        // Только враги. Бойцы игрока и союзники — без изменений.
        if (this.isPlayerControlled() || this.isAlliedWithPlayer()) return ret;
        if (!this.isPlacedOnMap() || !this.isAlive() || this.isDying()) return ret;

        local isTargeting = _targetedWithSkill != null;

        // --- Полностью скрыть ---
        if (mode == "Hide everything") {
            if (!isTargeting) return [];   // чистое наведение — карточки нет
            // при прицеливании оставляем только шанс попадания (id 3)
            local kept = [];
            foreach (e in ret) {
                if (("id" in e) && e.id == 3) kept.push(e);
            }
            return kept;
        }

