// Prevent empty collapsed parchment strip in nested_tooltips when actor.getTooltip() returns []
// while tactical_queryTileTooltipData still returns a metadata-only entry (e.g. contentType).
::Legacy.MH.hook("scripts/ui/screens/tooltip/tooltip_events", function(q) {
    q.tactical_queryTileTooltipData = @(__original) function() {
        local ret = __original();
        if (ret != null && ret.len() > 0 && ::Legacy.getEnemyTooltipMode() != "Off") {
            local hasRenderable = false;
            foreach (entry in ret) {
                if (typeof entry == "table" && ("type" in entry) && entry.type != null) {
                    hasRenderable = true;
                    break;
                }
            }
            if (!hasRenderable) return [];
        }
        return ret;
    };
});

